import{_ as r,a0 as p,w as i,s as l,ao as m,I as a,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux有問必答：如何在CentOS或RHEL 7上修改主機名 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在CentOS或RHEL 7上修改主機名 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在CentOS或RHEL 7上修改主機名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在CentOS或RHEL 7上修改主機名 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to change hostname on CentOS or RHEL 7","title":"Linux有問必答：如何在CentOS或RHEL 7上修改主機名","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to change hostname on CentOS or RHEL 7.md","filePath":"[post].md"}'),u={name:"201410/20140915 Linux FAQs with Answers--How to change hostname on CentOS or RHEL 7.md"};function h(d,t,L,C,c,x){const n=p("Link");return i(),l("div",null,[t[11]||(t[11]=m(`<h1 id="linux有問必答-如何在centos或rhel-7上修改主機名" tabindex="-1">Linux有問必答：如何在CentOS或RHEL 7上修改主機名 <a class="header-anchor" href="#linux有問必答-如何在centos或rhel-7上修改主機名" aria-label="Permalink to “Linux有問必答：如何在CentOS或RHEL 7上修改主機名”">​</a></h1><blockquote><p>問題：在CentOS/RHEL 7上修改主機名的正確方法是什麼（永久或臨時）？</p></blockquote><p>在CentOS或RHEL中，有三種定義的主機名:a、靜態的（static），b、瞬態的（transient），以及 c、靈活的（pretty）。“靜態”主機名也稱為內核主機名，是系統在啓動時從/etc/hostname自動初始化的主機名。“瞬態”主機名是在系統運行時臨時分配的主機名，例如，通過DHCP或mDNS服務器分配。靜態主機名和瞬態主機名都遵從作為互聯網域名同樣的字符限制規則。而另一方面，“靈活”主機名則允許使用自由形式（包括特殊/空白字符）的主機名，以展示給終端用户（如Dan&#39;s Computer）。</p><p>在CentOS/RHEL 7中，有個叫hostnamectl的命令列工具，它允許你查看或修改與主機名相關的配置。</p><p>要查看主機名相關的設置：</p><pre><code>$ hostnamectl status 
</code></pre><p><img src="https://farm4.staticflickr.com/3844/15113861225_e0e19783a7.jpg" alt=""></p><p>只查看靜態、瞬態或靈活主機名，分別使用“--static”，“--transient”或“--pretty”選項。</p><pre><code> $ hostnamectl status [--static|--transient|--pretty] 
</code></pre><p>要同時修改所有三個主機名：靜態、瞬態和靈活主機名：</p><pre><code>$ sudo hostnamectl set-hostname &lt;host-name&gt; 
</code></pre><p><img src="https://farm4.staticflickr.com/3855/15113489172_4e25ac87fa_z.jpg" alt=""></p><p>就像上面展示的那樣，在修改靜態/瞬態主機名時，任何特殊字符或空白字符會被移除，而提供的參數中的任何大寫字母會自動轉化為小寫。一旦修改了靜態主機名，/etc/hostname 將被自動更新。然而，/etc/hosts 不會更新以保存所做的修改，所以你需要手動更新/etc/hosts。</p><p>如果你只想修改特定的主機名（靜態，瞬態或靈活），你可以使用“--static”，“--transient”或“--pretty”選項。</p><p>例如，要永久修改主機名，你可以修改靜態主機名：</p><pre><code> $ sudo hostnamectl --static set-hostname &lt;host-name&gt; 
</code></pre><p>注意，你不必重啓機器以激活永久主機名修改。上面的命令會立即修改內核主機名。註銷並重新登入後在命令列提示來觀察新的靜態主機名。</p><hr>`,18)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://ask.xmodulo.com/change-hostname-centos-rhel-7.html"},{default:s(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/change-hostname-centos-rhel-7.html",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(n,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[2]||(t[2]=[e("GOLinux",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const g=r(u,[["render",h]]);export{_ as __pageData,g as default};
